class Solution {
public:
    int minOperations(vector<int>& nums,int k){
        vector<int> even(k,0),odd(k,0);
        for(int i=0;i<(int)nums.size();++i){
            int r=nums[i]%k;
            vector<int>& costs=(i%2?odd:even);
            for(int t=0;t<k;++t){
                int d=abs(r-t);
                costs[t]+=min(d,k-d);
            }
        }
        int ans=INT_MAX;
        for(int x=0;x<k;++x) for(int y=0;y<k;++y)
            if(x!=y) ans=min(ans,even[x]+odd[y]);
        return ans;
    }
};
